<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('finance_officer');$user=current_user();$flashes=render_flashes();$currentPage='approvals';$pageTitle='Approval Queue';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$cfg=fo_config($conn);
if($_SERVER['REQUEST_METHOD']==='POST'){fo_verify_csrf();$id=(int)($_POST['schedule_id']??0);$action=$_POST['action']??'';$s=$conn->prepare("SELECT id,created_by,status FROM stipend_schedules WHERE id=? LIMIT 1");$s->bind_param('i',$id);$s->execute();$sch=$s->get_result()->fetch_assoc();$s->close();if(!$sch||$sch['status']!=='awaiting_approval'){http_response_code(400);exit('Schedule unavailable.');}if(!fo_can_approve($cfg,(int)$sch['created_by'],$uid)){fo_flash('danger','Maker/checker segregation prevents self-approval.');header('Location: '.url('finance_officer/approvals.php'));exit;}if($action==='approve'){$conn->begin_transaction();try{$u=$conn->prepare("UPDATE stipend_schedules SET status='approved',approved_by=?,approved_at=NOW() WHERE id=? AND status='awaiting_approval'");$u->bind_param('ii',$uid,$id);$u->execute();$u->close();$u=$conn->prepare("INSERT INTO stipend_schedule_approval_history(schedule_id,action,acted_by,action_note) VALUES(?,'approved',?,'Final approval granted')");$u->bind_param('ii',$id,$uid);$u->execute();$u->close();$conn->commit();fo_activity($conn,$uid,'stipend_schedule_approved','Final-approved stipend schedule.','stipend_schedule',$id);fo_flash('success','Schedule approved.');}catch(Throwable $e){$conn->rollback();fo_flash('danger','Approval failed.');}header('Location: '.url('finance_officer/approvals.php'));exit;}}
$rows=[];$r=$conn->query("SELECT ss.id,ss.schedule_reference,ss.period_start,ss.period_end,ss.participant_count,ss.total_amount,ss.exception_count,ss.created_by,ss.submitted_at,u.first_name,u.last_name FROM stipend_schedules ss JOIN users u ON u.id=ss.created_by WHERE ss.status='awaiting_approval' ORDER BY ss.submitted_at");if($r)while($x=$r->fetch_assoc())$rows[]=$x;require __DIR__.'/_layout_start.php';?>
<div class="fo-page-header"><div><span>Maker / Checker</span><h2>Approval Queue</h2><p>Final approval is available only when segregation permits it.</p></div></div><div class="fo-alert fo-alert--info"><i class="fas fa-user-shield"></i><div><strong>Segregation <?= (int)$cfg['maker_checker_enabled']===1?'Enabled':'Disabled' ?></strong><span>When enabled, makers cannot final-approve their own schedules.</span></div></div><div class="fo-approval-grid"><?php foreach($rows as $x):$can=fo_can_approve($cfg,(int)$x['created_by'],$uid);?><article><div><strong><?= e($x['schedule_reference']) ?></strong><span class="fo-status <?= $can?'fo-status--success':'fo-status--warning' ?>"><?= $can?'Eligible to Approve':'Maker Locked' ?></span></div><p><?= e(fo_date($x['period_start'])) ?> - <?= e(fo_date($x['period_end'])) ?></p><div class="fo-metrics"><span><?= number_format((int)$x['participant_count']) ?> participants</span><span><?= e(fo_money($x['total_amount'])) ?></span><span><?= number_format((int)$x['exception_count']) ?> exceptions</span></div><small>Prepared by <?= e(trim($x['first_name'].' '.$x['last_name'])) ?></small><div><a class="fo-btn fo-btn--secondary" href="<?= url('finance_officer/schedule_view.php?id='.(int)$x['id']) ?>">Review</a><?php if($can):?><form method="post" style="display:inline"><input type="hidden" name="csrf_token" value="<?= e(fo_csrf_token()) ?>"><input type="hidden" name="schedule_id" value="<?= (int)$x['id'] ?>"><input type="hidden" name="action" value="approve"><button class="fo-btn fo-btn--primary">Approve</button></form><?php endif;?></div></article><?php endforeach;?></div><?php if(!$rows):?><div class="fo-card"><div class="fo-empty"><i class="fas fa-user-check"></i><strong>No schedules awaiting approval</strong></div></div><?php endif;?>
<?php require __DIR__.'/_layout_end.php';?>